            FDChoice(label: "Y aller discrètement", hint: "Tu y es allé sans le dire à personne. Deux heures formidables, une vidéo sur les réseaux, et un coup de fil du club le lundi.",
                     effects: [FDEffect(cond: "moral", delta: 6), FDEffect(rel: "coach", delta: -6), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Venir encourager sans jouer", hint: "Tu es venu encourager en survêtement, sans jouer une minute. Ils ont compris, à moitié.",
                     effects: [FDEffect(cond: "moral", delta: 3), FDEffect(rel: "coach", delta: 1), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Refuser franchement", hint: "Tu as refusé net en expliquant le règlement. Ils ont dit que c'était normal, du bout des lèvres.",
                     effects: [FDEffect(cond: "moral", delta: -3), FDEffect(rel: "coach", delta: 3)]),
        ]),
    FDSceneDef(
        id: "ami_derive", category: "Amis", minAge: 17, maxAge: 27,
        location: "Parking d'un club", character: "Un ami d'enfance",
        text: "Il t'attend adossé à une voiture sur le parking du club, à vingt heures passées. Vous avez appris à jouer ensemble sur le même terrain. Depuis, il a pris une autre route, et tout le quartier sait laquelle. Il veut « juste discuter cinq minutes », et deux joueurs vous regardent.",
        choices: [
            FDChoice(label: "Lui parler quand même", hint: "Tu lui as parlé une heure dans la voiture. Ça t'a fait du bien, et la photo a circulé le lendemain.",
                     effects: [FDEffect(cond: "reputation", delta: -4), FDEffect(cond: "moral", delta: 3), FDEffect(rel: "famille", delta: -2)]),
            FDChoice(label: "L'éviter", hint: "Tu es passé devant lui sans t'arrêter. Il n'a pas insisté, et vous ne vous êtes plus reparlé.",
                     effects: [FDEffect(cond: "moral", delta: -5), FDEffect(cond: "reputation", delta: 2)]),
            FDChoice(label: "Lui proposer un vrai coup de main", hint: "Tu lui as proposé une vraie aide, un contact, un travail. Il a dit qu'il verrait. Il n'a pas rappelé.",
                     effects: [FDEffect(money: -3000, delta: 0), FDEffect(cond: "moral", delta: 4)]),
        ]),
    FDSceneDef(
        id: "ami_jalousie", category: "Amis", minAge: 18, maxAge: 28,
        location: "Anniversaire", character: "Ton meilleur ami",
        text: "C'est son anniversaire, tout le monde a bu un verre de trop, et il le lâche à voix haute devant quinze personnes : « Depuis qu'il a signé, il ne nous calcule plus. » Le salon se tait d'un coup. Vous vous connaissez depuis le CP, et il n'a pas complètement tort.",
        choices: [
            FDChoice(label: "Répondre sèchement", hint: "Tu as répondu sec, devant tout le monde. La soirée s'est terminée à ce moment-là, et l'amitié aussi.",
                     effects: [FDEffect(cond: "moral", delta: -4), FDEffect(attr: .leadership, delta: 2)]),
            FDChoice(label: "Le prendre à part après", hint: "Tu l'as pris à part sur le balcon, après. Vous avez parlé une heure, et vous êtes rentrés ensemble.",
                     effects: [FDEffect(cond: "moral", delta: 4), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Payer la tournée en riant", hint: "Tu as payé la tournée en riant très fort. Personne n'a relevé, et le problème est resté entier.",
                     effects: [FDEffect(money: -800, delta: 0), FDEffect(cond: "moral", delta: 2), FDEffect(cond: "reputation", delta: 1)]),
        ]),
    FDSceneDef(
        id: "ami_pret_argent", category: "Amis", minAge: 19, maxAge: 32,
        location: "Téléphone", character: "Un ami",
        text: "Il appelle un dimanche soir : un local à reprendre, une occasion à ne pas laisser passer, il faut décider avant mercredi. Tu lui avais déjà avancé de quoi lancer sa première affaire, il y a trois ans. Il ne l'a jamais rendu, et aucun de vous deux n'a jamais reparlé de ça.",
        choices: [
            FDChoice(label: "Prêter sans conditions", hint: "Tu as envoyé l'argent sans rien demander. Il a dit qu'il n'oublierait pas — il l'avait déjà dit.",
                     effects: [FDEffect(money: -15000, delta: 0), FDEffect(cond: "moral", delta: 2)]),
            FDChoice(label: "Prêter avec un contrat écrit", hint: "Tu as prêté avec un vrai papier signé. Il a trouvé ça vexant, et il a signé quand même.",
                     effects: [FDEffect(money: -15000, delta: 0), FDEffect(attr: .sangfroid, delta: 2)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé cette fois-ci. Il a raccroché poliment, et il ne rappelle plus le dimanche.",
                     effects: [FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "form_test_physique", category: "Entraînement", minAge: 15, maxAge: 19,
        location: "Salle de musculation", character: "Préparateur physique",
        text: "Batterie de tests devant tout le groupe, les chronos projetés en direct sur l'écran du gymnase. Les anciens commentent chaque passage. Il reste le dernier sprint, tu es dans le rythme des meilleurs, et le préparateur te regarde en tenant son chronomètre un peu trop visiblement.",
        choices: [
            FDChoice(label: "Tout donner sur le dernier sprint", hint: "Tu as tout vidé sur le dernier sprint. Meilleur chrono du groupe affiché en grand — et deux jours de courbatures.",
                     effects: [FDEffect(attr: .vitesse, delta: 2), FDEffect(cond: "fatigue", delta: 12), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Gérer pour finir propre", hint: "Tu as géré pour finir propre partout. Aucun chrono marquant, aucune alerte non plus.",
                     effects: [FDEffect(attr: .endurance, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "form_gardien_doublure", category: "Poste", minAge: 16, maxAge: 23,
        location: "Terrain annexe", character: "Entraîneur des gardiens",
        text: "L'entraîneur des gardiens t'annonce la hiérarchie de la saison à froid, dans son bureau : tu commences numéro deux. Devant toi, un titulaire de trente-deux ans qui ne se blesse jamais. « Tu t'entraînes comme un titulaire et tu attends. C'est le métier. »",
        choices: [
            FDChoice(label: "Travailler double sans rien dire", hint: "Tu as travaillé double toute la saison sans jamais te plaindre. Le staff l'a vu ; les tribunes, jamais.",
                     effects: [FDEffect(attr: .agilite, delta: 3), FDEffect(cond: "fatigue", delta: 10), FDEffect(rel: "coach", delta: 5)]),
            FDChoice(label: "Demander un prêt", hint: "Tu as demandé un prêt pour aller jouer ailleurs. Le club l'a mal pris, et tu as gardé les mains chaudes.",
                     effects: [FDEffect(rel: "coach", delta: -3), FDEffect(cond: "confiance", delta: 2)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "form_scout_etranger", category: "Transfert", minAge: 16, maxAge: 19,
        location: "Tribune", character: "Recruteur étranger",
        text: "Il est arrivé la veille, il repart demain, et il est venu pour toi seul : le club t'a fait prévenir avant l'échauffement, ce qu'il n'aurait jamais dû faire. Tu l'aperçois en tribune, carnet ouvert, pendant que tu enfiles ton maillot. Quatre-vingt-dix minutes pour exister.",
        choices: [
            FDChoice(label: "Forcer ton jeu pour l'impressionner", hint: "Tu as forcé ton jeu pour marquer les esprits. Deux gestes magnifiques, six ballons perdus, et un rapport très mitigé.",
                     effects: [FDEffect(attr: .dribble, delta: 2), FDEffect(rel: "vestiaire", delta: -3), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Jouer ton match normalement", hint: "Tu as joué ton match comme les autres. Sobre, juste, sans éclat — c'est exactement ce qu'il cherchait.",
                     effects: [FDEffect(attr: .placement, delta: 2), FDEffect(rel: "coach", delta: 3), FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "form_langue_etrangere", category: "Transfert", minAge: 17, maxAge: 26,
        location: "Salle de réunion", character: "Traducteur du club",
        text: "Le club étranger qui te suit pose une condition avant même de parler chiffres : tu dois te mettre à leur langue tout de suite. Le traducteur assis en face de toi te tend un planning de cours quotidiens, en plus des séances, en plus des matchs, sur ton temps de repos.",
        choices: [
            FDChoice(label: "Prendre des cours tous les soirs", hint: "Tu as pris les cours tous les soirs, épuisé. Six mois plus tard, tu tenais une conversation dans leur vestiaire.",
                     effects: [FDEffect(cond: "fatigue", delta: 6), FDEffect(attr: .vision, delta: 2), FDEffect(rel: "media", delta: 3)]),
            FDChoice(label: "Refuser, ils s'adapteront", hint: "Tu as refusé en disant qu'ils s'adapteraient. Ils se sont adaptés — et le dossier a traîné six mois de plus.",
                     effects: [FDEffect(rel: "media", delta: -4), FDEffect(cond: "confiance", delta: 2)]),
        ]),
    FDSceneDef(
        id: "form_reserve_bloque", category: "Club", minAge: 18, maxAge: 23,
        location: "Terrain de la réserve", character: "Entraîneur de la réserve",
        text: "Six mois que tu es le meilleur joueur de la réserve, tous les week-ends, sans exception. Le groupe pro s'entraîne à cent mètres, derrière la même haie, et personne n'a traversé pour te voir. Ton entraîneur te l'a dit franchement : en haut, ton nom n'est jamais prononcé.",
        choices: [
            FDChoice(label: "Demander un rendez-vous à l'entraîneur pro", hint: "Tu es allé frapper à la porte de l'entraîneur pro. Il t'a reçu dix minutes, poliment. Il connaissait ton nom.",
                     effects: [FDEffect(rel: "coach", delta: -2), FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Continuer à empiler les performances", hint: "Tu as continué à empiler les performances sans rien dire. Deux mois plus tard, une blessure a ouvert la porte.",
                     effects: [FDEffect(attr: .determination, delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Faire passer le message par ton agent", hint: "Tu as fait passer le message par ton agent. Il a fait le tour du club, et le message est bien arrivé — pas dans le bon sens.",
                     effects: [FDEffect(rel: "agent", delta: 4), FDEffect(rel: "coach", delta: -4)]),
        ]),
    FDSceneDef(
        id: "form_mentor_ancien", category: "Vestiaire", minAge: 17, maxAge: 24,
        location: "Vestiaire", character: "Un ancien du club",
        text: "Il a trente-cinq ans, deux cents matchs et un genou en moins. Il te propose de le suivre partout pendant un mois : les soins, les repas, les séances vidéo, les trajets. « Je ne t'apprendrai rien sur le ballon. Je vais t'apprendre à durer. » Il ne le propose jamais deux fois.",
        choices: [
            FDChoice(label: "Accepter et tout observer", hint: "Tu l'as suivi partout pendant un mois. Tu as pris dix ans de métier en trente jours.",
                     effects: [FDEffect(attr: .placement, delta: 3), FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Décliner, tu apprends en jouant", hint: "Tu as décliné : tu apprends en jouant, pas en regardant. Il n'a plus jamais reproposé, à toi ni à un autre.",
                     effects: [FDEffect(attr: .determination, delta: 2), FDEffect(rel: "vestiaire", delta: -2)]),
        ]),
    FDSceneDef(
        id: "form_reglement_interne", category: "Vestiaire", minAge: 15, maxAge: 19,
        location: "Internat", character: "Surveillant de l'internat",
        text: "La résidence du club ferme à vingt-et-une heures, c'est écrit dans le règlement que tu as signé. Ce soir, la moitié du groupe passe par le parking arrière pour aller en ville. L'intendant fait sa ronde à vingt-trois heures, et tout le monde le sait.",
        choices: [
            FDChoice(label: "Les suivre", hint: "Tu les as suivis. Vous êtes rentrés à trois heures, personne n'a rien vu, et la séance du matin a été un supplice.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "coach", delta: -7), FDEffect(cond: "fatigue", delta: 9)]),
            FDChoice(label: "Rester et ne rien dire", hint: "Tu es resté dans ta chambre sans rien dire à personne. Tu as été le seul frais au réveil, et le seul à côté du groupe.",
                     effects: [FDEffect(rel: "coach", delta: 2), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Prévenir l'éducateur", hint: "Tu as prévenu l'intendant. Personne n'a été puni, et tout le monde a su d'où venait l'info.",
                     effects: [FDEffect(rel: "coach", delta: 7), FDEffect(rel: "vestiaire", delta: -10)]),
        ]),
    FDSceneDef(
        id: "form_poste_change", category: "Poste", minAge: 16, maxAge: 22,
        location: "Terrain d'entraînement", character: "Entraîneur principal",
        text: "Le coach t'arrête à la fin de la séance avec un tableau blanc et une idée fixe : te déplacer à un poste que tu n'as jamais occupé de ta vie. « Là où tu joues, tu seras correct dix ans. Là où je veux te mettre, tu peux devenir quelqu'un. » Il ne te laisse pas la nuit pour réfléchir.",
        choices: [
            FDChoice(label: "Accepter le changement", hint: "Tu as accepté. Trois mois horribles, à contretemps de tout — puis un déclic que personne n'avait vu venir.",
                     effects: [FDEffect(attr: .placement, delta: 3), FDEffect(attr: .vision, delta: 2), FDEffect(cond: "confiance", delta: -2)]),
            FDChoice(label: "Refuser et rester à ton poste", hint: "Tu as refusé et gardé ton poste. Tu y es bon, et le coach n'a plus jamais évoqué le sujet.",
                     effects: [FDEffect(rel: "coach", delta: -5), FDEffect(cond: "confiance", delta: 3)]),
        ]),
    FDSceneDef(
        id: "form_video_analyse", category: "Entraînement", minAge: 16, maxAge: 30,
        location: "Salle vidéo", character: "Analyste vidéo",
        text: "Séance vidéo devant tout le groupe. L'analyste passe vingt minutes sur tes erreurs, image par image, ralenti après ralenti, sans jamais élever la voix. Personne ne dit rien. Deux joueurs ont eu droit à trois minutes chacun ; toi, c'est un quart de la séance.",
        choices: [
            FDChoice(label: "Prendre des notes", hint: "Tu as pris des notes tout du long, sans lever les yeux. Le staff a remarqué, et deux de ces erreurs ont disparu.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(attr: .placement, delta: 2), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Contester une séquence", hint: "Tu as contesté une séquence, devant tout le monde. Tu avais raison sur celle-là, et tort sur le moment choisi.",
                     effects: [FDEffect(attr: .leadership, delta: 2), FDEffect(rel: "coach", delta: -4)]),
            FDChoice(label: "Encaisser en silence", hint: "Tu as encaissé sans un mot. La séance a fini par passer, la boule au ventre est restée trois jours.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "form_premiere_feuille", category: "Moment décisif", minAge: 17, maxAge: 22, once: true,
        location: "Vestiaire pro", character: "Entraîneur principal",
        text: "Ton nom est affiché sur la feuille de match professionnelle, en bas de la liste des remplaçants, imprimé comme les autres. Tu l'as relu quatre fois pour être sûr. Tu ne joueras probablement pas une seconde, mais il est là, écrit, sur du papier officiel.",
        choices: [
            FDChoice(label: "Prévenir toute ta famille", hint: "Tu as appelé toute la famille dans la foulée. Ils étaient douze en tribune pour te voir rester sur le banc.",
                     effects: [FDEffect(rel: "famille", delta: 8), FDEffect(cond: "moral", delta: 6), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Ne rien dire tant que tu n'as pas joué", hint: "Tu n'as prévenu personne. Tu as gardé la feuille pliée dans ton sac, et tu es entré à la 88e.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 8)]),
        ]),
    FDSceneDef(
        id: "form_premiere_entree", category: "Moment décisif", minAge: 17, maxAge: 23, once: true,
        location: "Bord du terrain", character: "Quatrième arbitre",
        text: "82e minute, le score est serré, le stade pousse. Le coach se retourne, cherche du regard sur le banc, et c'est ton nom qu'il crie. Tu retires ta chasuble d'un geste, le quatrième arbitre lève son panneau, et le stade voit un nom qu'il ne connaît pas.",
        choices: [
            FDChoice(label: "Réclamer le ballon dès la première seconde", hint: "Tu as réclamé le ballon dès ta première seconde sur le terrain. Tu l'as perdu, tu l'as redemandé, et le stade a retenu ça.",
                     effects: [FDEffect(attr: .dribble, delta: 2), FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "Jouer simple et propre", hint: "Tu as joué huit minutes simples et propres. Aucun geste marquant, aucune erreur — le coach a apprécié.",
                     effects: [FDEffect(attr: .passe, delta: 2), FDEffect(rel: "coach", delta: 5), FDEffect(attr: .placement, delta: 1), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "form_contrat_image", category: "Contrat", minAge: 17, maxAge: 22,
        location: "Bureau du club", character: "Juriste du club",
        text: "Le juriste du club fait glisser le contrat sur la table, page ouverte au bon paragraphe : tes droits à l'image, cédés au club, sans contrepartie, pour toute la durée du contrat. « C'est standard chez nous. » Ton agent n'est pas dans la pièce et ils ont choisi ce moment-là.",
        choices: [
            FDChoice(label: "Signer sans discuter", hint: "Tu as signé sans discuter. Le club utilise ton visage partout, gratuitement, depuis ce jour-là.",
                     effects: [FDEffect(rel: "president", delta: 5), FDEffect(money: 0, delta: 0), FDEffect(rel: "coach", delta: -3)]),
            FDChoice(label: "Négocier une clause", hint: "Tu as demandé à faire relire la clause. Ils ont soupiré, ils ont cédé sur la moitié, et tu as gagné un pourcentage.",
                     effects: [FDEffect(rel: "agent", delta: 5), FDEffect(rel: "president", delta: -4), FDEffect(money: 12000, delta: 0)]),
        ]),
    FDSceneDef(
        id: "form_reconversion_doute", category: "Mental", minAge: 18, maxAge: 24,
        location: "Chambre", character: "Toi-même",
        text: "Trois heures du matin, plafond de la chambre, et cette question qui revient depuis des semaines : combien de joueurs de ta génération vivront réellement de ça ? Tu as arrêté les études pour être là. Il est encore temps de reprendre à distance — dans un an, ce sera fini.",
        choices: [
            FDChoice(label: "S'inscrire à distance", hint: "Tu t'es inscrit à distance. Des soirées de cours en plus des séances, et une porte de sortie qui n'existait pas.",
                     effects: [FDEffect(attr: .vision, delta: 2), FDEffect(cond: "fatigue", delta: 6), FDEffect(rel: "famille", delta: 5)]),
            FDChoice(label: "Tout miser sur le football", hint: "Tu as tout misé sur le football, sans filet. C'est un choix qui rend meilleur, et qui coûte cher si ça tourne mal.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(rel: "famille", delta: -3)]),
        ]),
    FDSceneDef(
        id: "form_regime", category: "Hygiène de vie", minAge: 16, maxAge: 30,
        location: "Réfectoire", character: "Nutritionniste du club",
        text: "Le nutritionniste du club a établi un protocole strict, pesé, sans écart — il te l'a fait signer. Ta mère, elle, a préparé ton plat préféré pour le week-end, celui qu'elle fait depuis tes six ans, et elle a envoyé la photo dans la conversation de famille.",
        choices: [
            FDChoice(label: "Respecter le régime", hint: "Tu as respecté le protocole à la lettre, y compris ce week-end-là. Ta mère n'a rien dit, et le plat est parti au congélateur.",
                     effects: [FDEffect(cond: "forme", delta: 5), FDEffect(rel: "famille", delta: -3), FDEffect(attr: .endurance, delta: 1)]),
            FDChoice(label: "Craquer une fois", hint: "Tu as craqué une fois, et c'était très bon. Le pesage du lundi n'a pas trouvé ça drôle.",
                     effects: [FDEffect(cond: "forme", delta: -2), FDEffect(rel: "famille", delta: 4), FDEffect(cond: "moral", delta: 3)]),
        ]),
    FDSceneDef(
        id: "form_sommeil", category: "Hygiène de vie", minAge: 15, maxAge: 28,
        location: "Chambre", character: "Préparateur mental",
        text: "Le préparateur mental te montre les relevés de ton bracelet : cinq heures par nuit, en moyenne, depuis des mois. Il ne te fait pas la morale, il pose juste les chiffres à côté de tes notes de match, et la courbe descend exactement au même endroit.",
        choices: [
            FDChoice(label: "Accepter un protocole de sommeil", hint: "Tu as accepté son protocole : horaires fixes, pas d'écran, chambre noire. Trois semaines plus tard, tu ne reconnaissais plus tes fins de match.",
                     effects: [FDEffect(cond: "fatigue", delta: -14), FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Balayer le sujet", hint: "Tu as balayé le sujet en disant que tu avais toujours dormi comme ça. Et tu as continué à finir les matchs à l'agonie.",
                     effects: [FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "forme", delta: -4)]),
        ]),
    FDSceneDef(
        id: "form_charge_travail", category: "Entraînement", minAge: 16, maxAge: 32,
        location: "Salle de musculation", character: "Préparateur physique",
        text: "Le préparateur physique veut doubler ta charge pendant six semaines : deux séances par jour, musculation le matin, terrain l'après-midi, aucun jour off. « Tu sortiras de là transformé, ou tu sortiras de là blessé. Les deux existent, je ne vais pas te mentir. »",
        choices: [
            FDChoice(label: "Accepter le protocole complet", hint: "Tu as pris le protocole complet, six semaines, sans rien lâcher. Tu es sorti de là méconnaissable — et vidé.",
                     effects: [FDEffect(attr: .force, delta: 3), FDEffect(attr: .endurance, delta: 2), FDEffect(cond: "fatigue", delta: 16)]),
            FDChoice(label: "Négocier une version allégée", hint: "Vous avez négocié une version allégée, avec un jour de repos. Des progrès nets, sans jamais frôler la casse.",
                     effects: [FDEffect(attr: .force, delta: 1), FDEffect(attr: .endurance, delta: 1), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé le protocole. Ton corps est resté le même, et le préparateur ne t'a plus rien proposé.",
                     effects: [FDEffect(rel: "coach", delta: -4), FDEffect(cond: "fatigue", delta: -4)]),
        ]),
    FDSceneDef(
        id: "cpl_enfant_ecole", category: "Couple", minAge: 26, maxAge: 36,
        location: "Cour d'école", character: "Ta compagne",
