    FDSceneDef(
        id: "ves_brassard", category: "Vestiaire", minAge: 22, maxAge: 35,
        location: "Bureau du coach", character: "Entraîneur principal",
        text: "Le coach t'a fait venir dans son bureau : il hésite pour le brassard entre toi et un ancien qui a huit ans de club et deux ans de moins de temps de jeu. Il te demande franchement ce que tu en penses, et il écoutera vraiment ta réponse.",
        choices: [
            FDChoice(label: "Défendre ta candidature", hint: "Tu as défendu ta candidature, arguments à l'appui. Tu as eu le brassard, et l'ancien a compris comment.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "capitaine", delta: -4), FDEffect(cond: "confiance", delta: 4)]),
            FDChoice(label: "Soutenir l'ancien", hint: "Tu as soutenu l'ancien. Il a eu le brassard, il ne l'a pas oublié, et le vestiaire non plus.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "capitaine", delta: 8), FDEffect(attr: .leadership, delta: 1), FDEffect(cond: "fatigue", delta: 4)]),
        ]),
    FDSceneDef(
        id: "ves_jeune_perdu", category: "Vestiaire", minAge: 24, maxAge: 36,
        location: "Vestiaire", character: "Un jeune du centre",
        text: "Un gamin de dix-sept ans monté du centre traverse le vestiaire avec son sac, cherche une place, et finit par se changer debout dans un coin parce que personne ne lui a désigné de casier. Ça fait trois jours que ça dure. Toi, tu te souviens très bien de cette sensation-là.",
        choices: [
            FDChoice(label: "Le prendre sous ton aile", hint: "Tu l'as pris sous ton aile : casier, repas, trajets. Il est devenu titulaire deux ans plus tard, et il le raconte encore.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "moral", delta: 3), FDEffect(rel: "capitaine", delta: -3)]),
            FDChoice(label: "Le laisser se débrouiller", hint: "Tu l'as laissé se débrouiller, comme on t'a laissé le faire. Il a tenu six mois avant d'être prêté.",
                     effects: [FDEffect(cond: "moral", delta: -2)]),
        ]),
    FDSceneDef(
        id: "ves_traduction", category: "Vestiaire", minAge: 20, maxAge: 33,
        location: "Vestiaire", character: "Une recrue étrangère",
        text: "La recrue est là depuis un mois et n'a toujours pas prononcé trois phrases. Il mange seul, il s'entraîne seul, il ne comprend pas les consignes et fait semblant. Le club n'a prévu ni cours ni traducteur. Personne dans le vestiaire n'a fait le premier pas.",
        choices: [
            FDChoice(label: "L'inviter chez toi", hint: "Tu l'as invité chez toi un dimanche, avec sa famille. Il a parlé pour la première fois, et il n'a plus jamais joué contre toi.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "moral", delta: 4), FDEffect(rel: "capitaine", delta: -3)]),
            FDChoice(label: "Lui payer des cours", hint: "Tu lui as payé des cours de ta poche, sans le dire. Trois mois plus tard, il tenait une conversation au réfectoire.",
                     effects: [FDEffect(money: -3000, delta: 0), FDEffect(rel: "vestiaire", delta: 4)]),
            FDChoice(label: "Ne pas t'en mêler", hint: "Tu ne t'en es pas mêlé. Il a été prêté en janvier, et personne n'a su ce qu'il valait vraiment.",
                     effects: [FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "coa_systeme", category: "Coach", minAge: 19, maxAge: 34,
        location: "Salle vidéo", character: "Entraîneur principal",
        text: "Le coach déroule son nouveau système en salle vidéo, tableau à l'appui. Il y a onze cases et la tienne n'existe plus : ton poste a disparu de l'organigramme, remplacé par un rôle que tu n'as jamais joué. Il passe à la diapositive suivante sans te regarder.",
        choices: [
            FDChoice(label: "Demander un entretien", hint: "Tu as demandé un entretien le soir même. Il t'a expliqué son idée en détail, et il t'a trouvé une place dedans.",
                     effects: [FDEffect(rel: "coach", delta: 2), FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Apprendre le nouveau rôle", hint: "Tu as appris le nouveau rôle sans discuter, en y passant tes soirées. Trois mois durs, puis tu es devenu indispensable.",
                     effects: [FDEffect(attr: .placement, delta: 4), FDEffect(attr: .vision, delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Bouder", hint: "Tu as boudé pendant six semaines. Le coach a rempli la case avec quelqu'un d'autre.",
                     effects: [FDEffect(rel: "coach", delta: -7), FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "coa_licenciement", category: "Coach", minAge: 18, maxAge: 35,
        location: "Couloir du centre", character: "Entraîneur principal",
        text: "Le coach qui t'a lancé va sauter, tout le monde le sait. La direction consulte discrètement les cadres du vestiaire, un par un, dans un bureau du deuxième étage. Ton tour est cet après-midi. Ce que tu diras ne sortira pas de la pièce — c'est ce qu'on t'a promis.",
        choices: [
            FDChoice(label: "Le défendre publiquement", hint: "Tu l'as défendu publiquement, micro à la main. Il a sauté quand même, et il n'a jamais oublié qui avait parlé pour lui.",
                     effects: [FDEffect(rel: "coach", delta: 8), FDEffect(rel: "president", delta: -6), FDEffect(cond: "reputation", delta: 3)]),
            FDChoice(label: "Rester neutre", hint: "Tu es resté neutre, poliment, dans les deux camps. Personne ne t'en veut, personne ne te doit rien.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Prendre le camp du président", hint: "Tu as pris le camp du président. Le coach est parti, tu as gagné du crédit en haut, et deux joueurs ne te parlent plus.",
                     effects: [FDEffect(rel: "president", delta: 7), FDEffect(rel: "coach", delta: -9), FDEffect(rel: "vestiaire", delta: -4)]),
        ]),
    FDSceneDef(
        id: "coa_nouvel_entraineur", category: "Coach", minAge: 18, maxAge: 35,
        location: "Terrain d'entraînement", character: "Nouvel entraîneur",
        text: "Nouveau coach, première séance, et une phrase pour tout le monde dans le rond central : « Ce que vous avez fait avant ne m'intéresse pas. Tout le monde repart de zéro. » Il a apporté ses propres adjoints et son propre analyste. Onze places, vingt-cinq joueurs.",
        choices: [
            FDChoice(label: "Te montrer dès la première séance", hint: "Tu as tout donné dès la première séance, sur chaque exercice. Il t'a titularisé au premier match.",
                     effects: [FDEffect(attr: .determination, delta: 3), FDEffect(cond: "fatigue", delta: 8), FDEffect(rel: "coach", delta: 4)]),
            FDChoice(label: "Laisser passer l'orage", hint: "Tu as attendu que l'orage passe en travaillant normalement. Il a fait ses choix sans toi dedans.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "coa_engueulade", category: "Coach", minAge: 18, maxAge: 35,
        location: "Vestiaire", character: "Entraîneur principal",
        text: "Mi-temps. Il ne s'adresse pas au groupe, il s'adresse à toi, debout, devant les vingt autres, en reprenant chacune de tes pertes de balle. Ça dure deux minutes. Personne ne bouge, personne ne lève la tête, et il attend visiblement que tu répondes quelque chose.",
        choices: [
            FDChoice(label: "Répondre du tac au tac", hint: "Tu lui as répondu du tac au tac, devant tout le monde. Le vestiaire a adoré, et tu es resté sur le banc trois matchs.",
                     effects: [FDEffect(rel: "coach", delta: -8), FDEffect(attr: .leadership, delta: 3), FDEffect(rel: "vestiaire", delta: 4)]),
            FDChoice(label: "Baisser la tête et répondre sur le terrain", hint: "Tu as baissé la tête et tu es sorti mettre le feu en seconde période. Il ne l'a pas dit, mais il a compris.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(rel: "coach", delta: 5), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Demander à sortir", hint: "Tu as demandé à sortir. Il t'a remplacé à l'heure de jeu et la relation ne s'en est jamais remise.",
                     effects: [FDEffect(rel: "coach", delta: -10), FDEffect(cond: "moral", delta: -6)]),
        ]),
    FDSceneDef(
        id: "coa_confiance", category: "Coach", minAge: 19, maxAge: 34,
        location: "Bureau du coach", character: "Entraîneur principal",
        text: "Il ferme la porte de son bureau avant de parler, ce qu'il ne fait jamais. Il veut quelqu'un dans le vestiaire qui lui remonte l'ambiance, les tensions, ce qui se dit vraiment. « Pas un indicateur. Un relais. » La nuance est mince et tout le monde la connaît.",
        choices: [
            FDChoice(label: "Accepter le rôle", hint: "Tu as accepté. Tu as gagné son oreille, et tu passes désormais tes journées à peser chaque mot que tu répètes.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "coach", delta: 6), FDEffect(rel: "vestiaire", delta: -3)]),
            FDChoice(label: "Refuser, tu ne veux pas être un indic", hint: "Tu as refusé net : ce n'est pas ton rôle. Il a compris, il a demandé à un autre, et il t'a un peu moins consulté ensuite.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "coach", delta: -4)]),
        ]),
    FDSceneDef(
        id: "coa_temps_de_jeu", category: "Coach", minAge: 19, maxAge: 34,
        location: "Bureau du coach", character: "Entraîneur principal",
        text: "Trois matchs entiers sur le banc, sans une explication. Tu as demandé un rendez-vous lundi, il te reçoit jeudi, et il commence par regarder son téléphone. Le mercato d'hiver ouvre dans trois semaines et ton agent a déjà appelé deux fois cette semaine.",
        choices: [
            FDChoice(label: "Demander à partir en prêt", hint: "Tu as demandé à partir en prêt. Le club a accepté, et tu as rejoué tous les week-ends ailleurs.",
                     effects: [FDEffect(rel: "coach", delta: -3), FDEffect(cond: "confiance", delta: 2), FDEffect(rel: "agent", delta: 5)]),
            FDChoice(label: "Demander ce qu'il attend de toi", hint: "Tu lui as demandé ce qu'il attendait précisément de toi. Il te l'a dit, en trois points, et tu as rejoué le mois suivant.",
                     effects: [FDEffect(rel: "coach", delta: 5), FDEffect(attr: .determination, delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Menacer de ne plus t'entraîner", hint: "Tu as menacé de ne plus t'entraîner. Il t'a mis avec la réserve le lendemain matin.",
                     effects: [FDEffect(rel: "coach", delta: -10), FDEffect(cond: "reputation", delta: -4)]),
        ]),
    FDSceneDef(
        id: "coa_tactique_perso", category: "Coach", minAge: 21, maxAge: 35,
        location: "Salle vidéo", character: "Entraîneur adjoint",
        text: "L'adjoint t'attend après la séance avec une proposition claire : liberté totale devant, aucune consigne offensive, à une condition — tu doubles tes courses défensives et tu rentres sur chaque perte de balle. « Tu auras les clés. Tu paieras en kilomètres. »",
        choices: [
            FDChoice(label: "Accepter le contrat", hint: "Tu as accepté le contrat. Tu as eu les clés du jeu, et tu as terminé chaque match à l'agonie.",
                     effects: [FDEffect(attr: .endurance, delta: 3), FDEffect(attr: .vision, delta: 2), FDEffect(cond: "fatigue", delta: 10)]),
            FDChoice(label: "Négocier un rôle plus offensif", hint: "Tu as négocié un rôle plus haut, avec moins de replis. Il a cédé à moitié, et tu as gardé un peu des deux.",
                     effects: [FDEffect(attr: .tir, delta: 2), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "coa_stage_commando", category: "Coach", minAge: 18, maxAge: 34,
        location: "Camp de préparation", character: "Préparateur physique",
        text: "Cinq jours en montagne, deux séances par jour, pas un ballon de la semaine : côtes, sacs lestés, sommeil en dortoir. Le préparateur annonce le programme le premier soir sans sourire. Deux joueurs sont déjà revenus cassés du stage de l'an dernier.",
        choices: [
            FDChoice(label: "Tout avaler sans broncher", hint: "Tu as tout avalé sans jamais te plaindre, en tête de groupe. Tu es rentré transformé — et le mollet a tiré pendant un mois.",
                     effects: [FDEffect(attr: .endurance, delta: 4), FDEffect(cond: "fatigue", delta: 18), FDEffect(rel: "coach", delta: 6)]),
            FDChoice(label: "Lever le pied discrètement", hint: "Tu as levé le pied discrètement sur les dernières séries. Personne n'a rien vu, et tu es rentré entier.",
                     effects: [FDEffect(cond: "fatigue", delta: 8), FDEffect(rel: "coach", delta: -4)]),
        ]),
    FDSceneDef(
        id: "ent_seance_tirs", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur des attaquants",
        text: "Atelier finition, dix ballons chacun, le groupe entier assis derrière la cage à commenter. L'entraîneur des attaquants compte à voix haute. Les deux joueurs avant toi ont mis huit sur dix. Le gardien titulaire s'est mis dans les buts exprès.",
        choices: [
            FDChoice(label: "Frapper en puissance", hint: "Tu as tout mis en puissance, sans réfléchir. Trois lucarnes, quatre au-dessus, et un vestiaire debout sur les trois.",
                     effects: [FDEffect(attr: .tir, delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Travailler le placement du ballon", hint: "Tu as tout placé, sans forcer. Huit sur dix, aucun cri, et un entraîneur qui a noté le chiffre.",
                     effects: [FDEffect(attr: .tir, delta: 1), FDEffect(attr: .placement, delta: 2), FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "fatigue", delta: 9)]),
        ]),
    FDSceneDef(
        id: "ent_duels", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain d'entraînement", character: "Un défenseur du groupe",
        text: "Atelier duels, un contre un, et le tirage te met en face du joueur le plus dur du vestiaire — celui que les jeunes évitent depuis toujours. Il a déjà sorti deux adversaires de l'exercice ce matin. Il te regarde arriver sans rien dire.",
        choices: [
            FDChoice(label: "Chercher le contact", hint: "Tu as cherché le contact à chaque ballon. Vous êtes sortis tous les deux marqués, et il t'a serré la main à la fin.",
                     effects: [FDEffect(attr: .force, delta: 3), FDEffect(cond: "fatigue", delta: 8), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "Jouer sur la vitesse", hint: "Tu l'as pris en vitesse, encore et encore, sans jamais le toucher. Il s'est agacé, et tout le groupe l'a vu.",
                     effects: [FDEffect(attr: .vitesse, delta: 2), FDEffect(attr: .agilite, delta: 2), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ent_coups_francs", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur adjoint",
        text: "Le club a perdu son tireur cet été. Le staff organise un concours sur trois soirs : trois candidats, vingt ballons chacun, l'adjoint qui note tout. Tu es le moins bien classé des trois après la première séance, et personne ne s'attend à toi.",
        choices: [
            FDChoice(label: "Rester une heure de plus chaque soir", hint: "Tu es resté une heure de plus chaque soir pendant trois semaines. Le poste est devenu le tien, et tes soirées y sont passées.",
                     effects: [FDEffect(attr: .tir, delta: 3), FDEffect(cond: "fatigue", delta: 10), FDEffect(attr: .determination, delta: 2)]),
            FDChoice(label: "Laisser la place au spécialiste", hint: "Tu as laissé la place au spécialiste. C'est plus juste, et tu as regardé quelqu'un d'autre marquer sur coup franc en finale.",
                     effects: [FDEffect(rel: "vestiaire", delta: 3), FDEffect(attr: .sangfroid, delta: 1), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ent_gardien_specifique", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain annexe", character: "Entraîneur des gardiens",
        text: "L'entraîneur des gardiens a préparé la série qu'il réserve à ceux qu'il veut pousser : cinquante arrêts réflexes en dix minutes, ballons envoyés à bout portant, sans pause. Au trentième, les bras ne répondent plus. Il ne dit rien, il continue à envoyer.",
        choices: [
            FDChoice(label: "Aller au bout de la série", hint: "Tu es allé au bout des cinquante. Les vingt derniers étaient horribles, et ce sont ceux-là qui t'ont fait progresser.",
                     effects: [FDEffect(attr: .agilite, delta: 3), FDEffect(cond: "fatigue", delta: 12), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "S'arrêter à trente", hint: "Tu t'es arrêté à trente, proprement. Il a hoché la tête et rangé les ballons sans commentaire.",
                     effects: [FDEffect(attr: .agilite, delta: 1), FDEffect(cond: "fatigue", delta: 5)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "ent_relance", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Surface de réparation", character: "Entraîneur des gardiens",
        text: "Le coach veut relancer court à chaque fois, y compris quand deux attaquants viennent presser à cinq mètres de ta surface. Il l'a répété trois fois en réunion. Le stade, lui, hurle dès que le ballon traîne au sol dans ta surface — et le stade sera là dimanche.",
        choices: [
            FDChoice(label: "Jouer le jeu à chaque ballon", hint: "Tu as joué court à chaque ballon, même sous pression. Deux frayeurs, une passe décisive depuis ta surface, et un coach conquis.",
                     effects: [FDEffect(attr: .passe, delta: 3), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: -2)]),
            FDChoice(label: "Dégager long dès que ça chauffe", hint: "Tu as dégagé long dès que ça chauffait. Pas un but encaissé bêtement, et un coach qui a arrêté de compter sur toi pour ça.",
                     effects: [FDEffect(attr: .force, delta: 2), FDEffect(rel: "coach", delta: -4)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "ent_ligne_defensive", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur adjoint",
        text: "Deux heures de ligne défensive sous le soleil : monter, descendre, se replacer, au cordeau, sans ballon. L'adjoint arrête l'exercice au moindre décalage d'un mètre. Personne ne dirige la ligne, et à chaque arrêt, les quatre se regardent en attendant que quelqu'un parle.",
        choices: [
            FDChoice(label: "Prendre la direction de la ligne", hint: "Tu as pris la ligne en main et tu as parlé pendant deux heures. Tu es sorti sans voix, et la ligne a tenu tout le mois.",
                     effects: [FDEffect(attr: .leadership, delta: 3), FDEffect(attr: .placement, delta: 3), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Suivre sans parler", hint: "Tu as suivi les autres sans un mot. La séance est passée, et la ligne a continué à se chercher un patron.",
                     effects: [FDEffect(attr: .placement, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ],
        positions: [.defenseur]),
    FDSceneDef(
        id: "ent_pressing", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur principal",
        text: "Nouveau plan de pressing : dix secondes pour récupérer après chaque perte, sinon tout l'exercice recommence pour tout le monde. Le coach chronomètre. On en est à la cinquième reprise, le groupe commence à s'énerver, et il en reste trente minutes.",
        choices: [
            FDChoice(label: "Mener le pressing du groupe", hint: "Tu as mené le pressing, en gueulant, en courant pour deux. Le groupe a suivi et l'exercice est enfin passé.",
                     effects: [FDEffect(attr: .endurance, delta: 3), FDEffect(attr: .leadership, delta: 2), FDEffect(cond: "fatigue", delta: 12)]),
            FDChoice(label: "Économiser tes courses", hint: "Tu as économisé tes courses en te plaçant bien. Tu as fini frais, et deux coéquipiers l'ont remarqué.",
                     effects: [FDEffect(cond: "fatigue", delta: 4), FDEffect(rel: "coach", delta: -4)]),
        ]),
    FDSceneDef(
        id: "ent_analyse_perso", category: "Entraînement", minAge: 18, maxAge: 36,
        location: "Salle vidéo", character: "Analyste vidéo",
        text: "L'analyste te propose un suivi individuel : deux heures par semaine, sur ton temps libre, à décortiquer tes propres matchs image par image. Il ne le propose pas à tout le monde. Ce sont deux heures prises sur les seules que tu as pour souffler.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté les deux heures hebdomadaires. Tu comprends mieux ton jeu, et tu ne récupères plus vraiment.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(attr: .placement, delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Refuser, tu préfères récupérer", hint: "Tu as refusé pour préserver ta récupération. Tu es frais, et tu continues à refaire les mêmes erreurs.",
                     effects: [FDEffect(cond: "fatigue", delta: -6), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "ent_musculation", category: "Entraînement", minAge: 17, maxAge: 34,
        location: "Salle de musculation", character: "Préparateur physique",
        text: "Le préparateur veut te faire prendre quatre kilos de masse en trois mois : trois séances de charges par semaine, alimentation imposée, contrôle du poids tous les lundis. « Tu vas être plus lourd. Au début, tu seras aussi plus lent. Il faut passer ce trou-là. »",
        choices: [
            FDChoice(label: "Suivre le programme complet", hint: "Tu as suivi le programme complet. Quatre kilos, plus personne ne te bouge dans les duels — et deux dixièmes perdus sur trente mètres.",
                     effects: [FDEffect(attr: .force, delta: 4), FDEffect(attr: .vitesse, delta: -1), FDEffect(cond: "fatigue", delta: 12)]),
            FDChoice(label: "Prioriser l'explosivité", hint: "Tu as tout mis sur l'explosivité plutôt que la masse. Tu pars toujours plus vite, et tu te fais toujours écarter.",
                     effects: [FDEffect(attr: .agilite, delta: 2), FDEffect(attr: .vitesse, delta: 2), FDEffect(cond: "fatigue", delta: 8)]),
        ]),
    FDSceneDef(
        id: "ent_recuperation", category: "Entraînement", minAge: 18, maxAge: 36,
        location: "Centre de soins", character: "Kinésithérapeute",
        text: "Le kiné a affiché ton protocole sur la porte de la salle de soins : cryothérapie, massages, électrostimulation, tous les deux jours, deux heures à chaque fois. C'est long, c'est ennuyeux, et ça tombe systématiquement sur tes seules après-midi libres.",
        choices: [
            FDChoice(label: "Tout suivre à la lettre", hint: "Tu as tout suivi à la lettre pendant toute la saison. Zéro pépin musculaire, et zéro après-midi à toi.",
                     effects: [FDEffect(cond: "fatigue", delta: -16), FDEffect(cond: "forme", delta: 5), FDEffect(rel: "coach", delta: -2)]),
            FDChoice(label: "Y aller quand tu y penses", hint: "Tu y es allé quand tu y pensais. Tu as gagné du temps libre, et tu as raté trois semaines en février.",
                     effects: [FDEffect(cond: "fatigue", delta: -4), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ent_jeune_prodige", category: "Entraînement", minAge: 24, maxAge: 36,
        location: "Terrain d'entraînement", character: "Un jeune du centre",
        text: "Un gamin de dix-sept ans t'élimine deux fois dans le même exercice, devant tout le groupe, avec le même geste. La deuxième fois, le vestiaire entier a réagi. Il ne célèbre pas, il ne dit rien, il retourne se placer — ce qui est encore pire.",
        choices: [
            FDChoice(label: "Le féliciter franchement", hint: "Tu es allé le féliciter franchement devant tout le monde. Le groupe a apprécié, et lui ne t'oubliera jamais.",
                     effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "fatigue", delta: 9)]),
            FDChoice(label: "Le corriger au duel suivant", hint: "Tu l'as corrigé au duel suivant, un peu trop fort. Le staff a levé les yeux, et il n'a plus retenté le geste sur toi.",
