                     effects: [FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "mat_serie_victoires", category: "Match important", minAge: 18, maxAge: 36,
        location: "Vestiaire", character: "Un journaliste",
        text: "Dixième victoire consécutive, record du club égalé. En zone mixte, le journaliste pose la question qui piège tout le monde : est-ce que cette équipe peut tout gagner cette saison ? Derrière lui, six caméras. Le coach a demandé la veille de rester humbles.",
        choices: [
            FDChoice(label: "Promettre le titre", hint: "Tu as promis le titre, devant les caméras. Le vestiaire adverse a affiché ta phrase toute la saison.",
                     effects: [FDEffect(rel: "media", delta: 5), FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "vestiaire", delta: -3)]),
            FDChoice(label: "Rester prudent", hint: "Tu es resté prudent, match après match. Personne n'a repris ta réponse, et c'était le but.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "mat_but_contre_camp", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Ta propre surface", character: "Le tableau d'affichage",
        text: "80e minute, tu dévies un centre anodin dans ton propre but. Le stade te siffle, ton nom passe dans les haut-parleurs comme buteur, et deux coéquipiers évitent ton regard. Il reste dix minutes et le score est désormais contre vous.",
        choices: [
            FDChoice(label: "Aller chercher le pardon dans le jeu", hint: "Tu es allé chercher le pardon dans le jeu, ballon après ballon. Tu as obtenu le penalty de l'égalisation à la 89e.",
                     effects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Te recroqueviller", hint: "Tu t'es recroquevillé. Tu n'as plus demandé un ballon jusqu'au coup de sifflet final.",
                     effects: [FDEffect(cond: "confiance", delta: -8), FDEffect(cond: "moral", delta: -6)]),
        ]),
    FDSceneDef(
        id: "mat_triplé", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Terrain", character: "Le speaker",
        text: "Deux buts au compteur et un penalty accordé à la 75e. Le ballon est dans tes mains, le triplé est là. À deux mètres, un coéquipier qui n'a plus marqué depuis quatre mois te le demande à voix basse, sans insister. Le stade scande déjà ton nom.",
        choices: [
            FDChoice(label: "Tirer et chercher le triplé", hint: "Tu l'as tiré et tu as eu ton triplé. Le stade a scandé ton nom, et lui est sorti sans marquer.",
                     effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "vestiaire", delta: -4)]),
            FDChoice(label: "Lui laisser le ballon", hint: "Tu lui as donné le ballon. Il a marqué, il est venu pleurer dans tes bras, et tout le vestiaire a vu.",
                     effects: [FDEffect(rel: "vestiaire", delta: 8), FDEffect(attr: .leadership, delta: 4), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "mat_hostilite_exterieur", category: "Match important", minAge: 18, maxAge: 36,
        location: "Stade adverse", character: "Supporters adverses",
        text: "Des cris racistes montent d'une tribune entière depuis la demi-heure de jeu, dirigés vers ton banc et vers toi. L'arbitre a fait une première annonce, sans effet. Il vient te voir pour savoir si tu veux qu'il applique la procédure et arrête la rencontre.",
        choices: [
            FDChoice(label: "Demander l'arrêt du match", hint: "Tu as demandé l'arrêt du match. Vous êtes rentrés au vestiaire, la fédération a sanctionné le club, et le débat a occupé le pays pendant une semaine.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(rel: "media", delta: 6), FDEffect(rel: "fans", delta: 3), FDEffect(cond: "forme", delta: -3)]),
            FDChoice(label: "Continuer à jouer", hint: "Tu as demandé à continuer. Vous avez gagné, tu n'as rien lâché, et la tribune n'a jamais été sanctionnée.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "moral", delta: -6)]),
        ]),
    FDSceneDef(
        id: "mat_maillot_echange", category: "Match important", minAge: 18, maxAge: 36,
        location: "Couloir", character: "Un adversaire",
        text: "Mi-temps, dans le tunnel, un des meilleurs joueurs du monde te tape sur l'épaule et te propose son maillot pour la fin du match. Tu as vingt-deux ans, il en a trente-trois, et il reste quarante-cinq minutes à jouer où vous serez adversaires directs.",
        choices: [
            FDChoice(label: "Accepter tout de suite", hint: "Tu as dit oui tout de suite, à la mi-temps. Il a souri — et il t'a mangé pendant quarante-cinq minutes.",
                     effects: [FDEffect(cond: "moral", delta: 4), FDEffect(rel: "vestiaire", delta: -3), FDEffect(rel: "media", delta: -2)]),
            FDChoice(label: "Lui dire après le match", hint: "Tu lui as dit qu'on verrait après le match. Il a apprécié, et tu as joué la seconde période comme un adversaire.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "forme", delta: -3)]),
